local _K={241,140,218,155,95,42,13,192,86,58,35,234,119,188,42,225,176,156,130,203,90,253,244,179,174,180,127,18,172,189,24,173}
local _K2={176,156,130,203,90,253,244,179,174,180,127,18,172,189,24,173}
local function _b64(d)
local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
d=d:gsub('[^'..b..'=]','')
return(d:gsub('.',function(x)
if x=='='then return''end
local r,f='',(b:find(x)-1)
for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and'1'or'0')end
return r
end):gsub('%d%d%d?%d?%d?%d?%d?%d?',function(x)
if#x~=8 then return''end
local c=0
for i=1,8 do c=c+(x:sub(i,i)=='1'and 2^(8-i)or 0)end
return string.char(c)
end))
end
local function _xor(a,c)
if bit32 and bit32.bxor then return bit32.bxor(a,c)end
local r,p=0,1
for _=0,7 do local x,y=a%2,c%2 if x~=y then r=r+p end a,c,p=(a-x)/2,(c-y)/2,p*2 end
return r
end
local function _stage1()
local bin=_b64(table.concat(_P))
local o={}
for i=1,#bin do
local b=bin:byte(i)
o[i]=_xor(_xor(b,_K2[((i-1)%16)+1]),((i-1)*7)%256)
end
return o
end
local function _vm(prog)
local out={}
local i=1
local n=#prog
while i<=n do
local op=prog[i]
local arg=prog[i+1] or 0
i=i+2
if op==1 then out[#out+1]=arg
elseif op==2 then -- nop
end
end
return out
end
local function _dec(enc)
local o={}
for i=1,#enc do
local x=enc[i]
local idx=i-1
x=_xor(x,_K[((idx+7)%32)+1])
x=(x-((idx*31)%256))%256
x=_xor(x,_K[(idx%32)+1])
o[i]=string.char(x)
end
return table.concat(o)
end
local prog=_stage1()
local enc=_vm(prog)
local src=_dec(enc)
local fn,err=loadstring(src)
if not fn then error("[Cr4ck] VM "..tostring(err)) end
fn()
